J(id='schulbegleiter', field='soziales', name='Schulbegleiter/in (Integrationshelfer)',
  search='schulbegleitung schulbegleiterin integrationshelfer integrationshelferin inklusionsassistenz teilhabeassistenz schulassistenz quereinstieg',
  short='Kinder mit Unterstützungsbedarf im Schulalltag begleiten – oft ohne Fachausbildung möglich.',
  desc='Bewerbung als Schulbegleiter/in bzw. Integrationshelfer: zwei Anschreiben für Quereinstieg und Erfahrung, Lebenslauf mit Foto-Platzhalter und Tipps für das Gespräch.',
  intro='Schulbegleiterinnen und Schulbegleiter unterstützen ein Kind mit Behinderung oder besonderem Förderbedarf im Unterricht und in den Pausen. Viele Träger stellen auch Menschen ohne pädagogische Ausbildung ein, wenn Haltung, Geduld und Zuverlässigkeit stimmen. Arbeitszeiten richten sich nach dem Stundenplan, Ferien sind oft unbezahlt oder werden ausgeglichen – frag nach.',
  lookFor=['Geduld, Ruhe und Verlässlichkeit – das Kind braucht eine feste Bezugsperson',
           'Erfahrung mit Kindern, gern mit Autismus, ADHS oder körperlichen Einschränkungen',
           'Bereitschaft zur Zusammenarbeit mit Lehrkräften und Eltern, ohne den Unterricht zu übernehmen',
           'Eventuell pflegerische Hilfen (Toilettengang, Essen) je nach Kind',
           'Erweitertes Führungszeugnis'],
  letters=[
    L('Quereinstieg als Mutter mit Teilzeitwunsch', 'quereinstieg', 'Schulbegleiterin an einer Grundschule (Teilzeit, vormittags)',
      T('Inklusionsdienst Pfalz gGmbH', 'Maximilianstraße 12', '67433 Neustadt an der Weinstraße', 'f', 'Ritter'),
      ['ich bin gelernte Industriekauffrau und habe zwölf Jahre im Einkauf gearbeitet. Seit meine Tochter mit ADHS die Grundschule besucht, kenne ich Schulbegleitung aus Elternsicht – und ich habe gesehen, was eine gute Begleiterin bewirkt.',
       'Was ich mitbringe: Ich bleibe ruhig, wenn es laut wird, und finde schnell heraus, was ein Kind gerade braucht, ob eine Pause, eine klare Ansage oder einfach jemand, der danebensitzt. Im letzten Schuljahr habe ich ehrenamtlich die Lesepatenschaft in der Klasse meiner Tochter übernommen und zweimal pro Woche mit drei Kindern gelesen.',
       'Mir ist klar, dass ich als Schulbegleiterin nicht unterrichte, sondern dem Kind helfe, am Unterricht teilzunehmen. Die Absprachen mit Lehrkräften und Eltern sind mir deshalb wichtig. Ich kann montags bis freitags von 7:45 bis 13:00 Uhr arbeiten. Ein erweitertes Führungszeugnis habe ich beantragt.'],
      ['Lebenslauf', 'Arbeitszeugnis', 'Bestätigung Lesepatenschaft']),
    L('Mit Erfahrung in der Begleitung eines autistischen Kindes', 'erfahren', 'Schulbegleiter für einen Schüler der Sekundarstufe',
      T('Lebenshilfe Ludwigshafen', 'Bürgermeister-Grünzweig-Straße 30', '67059 Ludwigshafen', 'none'),
      ['drei Jahre lang habe ich einen Jungen mit Autismus von der fünften bis zur siebten Klasse begleitet. Er hat jetzt so viel Selbstständigkeit gewonnen, dass die Stundenzahl der Begleitung reduziert wird. Ich suche deshalb eine neue Begleitung, gern wieder im Autismusbereich.',
       'Gemeinsam mit seinen Lehrkräften habe ich Rückzugsorte und einen visuellen Tagesplan eingeführt. Bei Reizüberflutung habe ich ihn in einen ruhigen Raum begleitet und mit ihm Strategien entwickelt, damit er das irgendwann selbst kann. Inzwischen meldet er sich ab, bevor es zu viel wird. Das war unser größter Erfolg.',
       'Vor der Schulbegleitung war ich Fitnesstrainer. Bewegungspausen sind deshalb ein festes Werkzeug von mir. Ich habe an einer Fortbildung zu Autismus im Schulalltag teilgenommen und kann sofort beginnen.'],
      ['Lebenslauf', 'Arbeitszeugnis', 'Fortbildungsbescheinigung'], frm=['Luca Ferrari', 'Rheinuferstraße 4', '67061 Ludwigshafen']),
  ],
  cv=dict(avatar='a04', design='modern', accent=4, name='Christina Becker', title='Schulbegleiterin', street='Hauptstraße 101', city='67433 Neustadt an der Weinstraße',
    exp=[['08/2025', '07/2026', 'Lesepatin (ehrenamtlich)', 'Grundschule Am Weinberg', 'Neustadt', '- Lesetraining mit drei Kindern, zweimal pro Woche'],
         ['08/2013', '07/2025', 'Industriekauffrau im Einkauf', 'Pfälzer Maschinenbau GmbH', 'Neustadt', '- Lieferantenkommunikation und Bestellwesen\n- Einarbeitung von Auszubildenden'],
         ['08/2010', '07/2013', 'Ausbildung zur Industriekauffrau', 'Pfälzer Maschinenbau GmbH', 'Neustadt', '']],
    edu=[['2001', '2010', 'Fachhochschulreife', 'BBS Neustadt', 'Neustadt', '']],
    courses=[['', '2026', 'Grundlagen Schulbegleitung (40 Std.)', 'Volkshochschule Neustadt', '', ''], ['', '2026', 'Erste Hilfe am Kind', 'DRK', '', '']],
    skills=[['Strukturierung und Organisation', 5], ['Ruhe in Konfliktsituationen', 4], ['Lesetraining', 3], ['Kommunikation mit Eltern', 4], ['MS Office', 4]],
    langs=[['Deutsch', 'native'], ['Englisch', 'B2']],
    hobbies='Wandern im Pfälzerwald, Elternbeirat'),
  do=['Erzähl, was du aus eigener Erfahrung über Kinder mit Förderbedarf weißt.', 'Sag, zu welchen Zeiten du verlässlich da bist.', 'Zeig, dass du deine Rolle neben der Lehrkraft verstehst.'],
  dont=['Dich als Ersatzlehrkraft anbieten.', 'Diagnosen eines Kindes aus deinem Umfeld detailliert schildern.', 'Die Ferienregelung ungeklärt lassen.'],
  questions=['Was tun Sie, wenn das Kind den Unterricht stört?', 'Wie gehen Sie damit um, wenn Lehrkraft und Eltern unterschiedliche Erwartungen haben?', 'Wie fördern Sie Selbstständigkeit?', 'Sind Sie bereit, bei Toilettengängen zu helfen?'],
  faq=[F('Brauche ich eine Ausbildung als Schulbegleiter?', 'Nicht immer. Viele Träger stellen Quereinsteiger ein und schulen sie. Bei Kindern mit hohem Pflege- oder Förderbedarf wird teils eine Fachkraft verlangt, etwa Heilerziehungspfleger oder Erzieherin.'),
       F('Werde ich in den Ferien bezahlt?', 'Das ist je nach Träger und Vertrag unterschiedlich: manche zahlen weiter, andere setzen Überstunden ein oder beschäftigen in den Ferien anderswo. Frag im Gespräch konkret danach.')],
  related=['erzieherin', 'heilerziehungspfleger', 'sozialarbeiter', 'nachhilfelehrer'])

J(id='lehrer-quereinstieg', field='soziales', name='Lehrkraft im Quereinstieg',
  search='quereinsteiger lehrer seiteneinstieg lehramt lehrerin vertretungslehrer schule mint lehrkraft ohne lehramt',
  short='Mit Fachstudium an die Schule – Seiteneinstieg, Quereinstieg oder Vertretung.',
  desc='Bewerbung als Lehrkraft im Quereinstieg: Musteranschreiben für Seiteneinstieg mit MINT-Studium und Vertretungsstelle, Lebenslauf und ehrliche Hinweise zu den Regeln der Länder.',
  intro='Viele Bundesländer holen Fachleute ohne Lehramtsstudium an die Schulen, vor allem in Mangelfächern. Die Wege heißen je nach Land Quereinstieg, Seiteneinstieg oder Vertretung und unterscheiden sich stark: Voraussetzungen, berufsbegleitendes Referendariat, Bezahlung. Prüf die Regeln deines Landes, bevor du schreibst, und zeig im Anschreiben, warum du unterrichten willst und was du fachlich mitbringst.',
  lookFor=['Ein Hochschulabschluss, aus dem sich meist ein oder zwei Unterrichtsfächer ableiten lassen – die genauen Anforderungen legt jedes Land selbst fest',
           'Erfahrung im Erklären: Nachhilfe, Ausbildung von Azubis, Trainertätigkeit, Lehraufträge',
           'Bereitschaft zur berufsbegleitenden Qualifizierung oder zum Vorbereitungsdienst',
           'Belastbarkeit, Klassenführung, Freude an Jugendlichen'],
  letters=[
    L('Ingenieurin mit Ziel Physik und Mathematik', 'quereinstieg', 'Lehrkraft für Physik und Mathematik im Seiteneinstieg',
      T('Gesamtschule Am Schillerpark', 'Schillerstraße 40', '45127 Essen', 'm', 'Krüger'),
      ['seit elf Jahren entwickle ich Messtechnik für Windkraftanlagen. Erklärt habe ich in dieser Zeit fast genauso viel wie entwickelt: Azubis, Werkstudenten, Kunden, die wissen wollen, warum ihr Sensor ausfällt. Ich möchte das jetzt zu meinem Beruf machen und an Ihrer Schule Physik und Mathematik unterrichten.',
       'Mit meinem Diplom in Elektrotechnik erfülle ich nach Auskunft der Bezirksregierung die Voraussetzungen für den Seiteneinstieg in beiden Fächern. Unterrichtserfahrung habe ich aus fünf Jahren als Betreuerin der Schüler-AG „Jugend forscht“ in unserem Unternehmen. Eine Gruppe aus der neunten Klasse hat mit einem selbst gebauten Windmesser den Landeswettbewerb erreicht. Ich weiß, dass eine Klasse mit 28 Jugendlichen etwas anderes ist als eine AG mit sechs Freiwilligen.',
       'Deshalb habe ich im Frühjahr zwei Wochen in einer achten Klasse hospitiert und einige Stunden selbst gehalten. Die pädagogische Einführung und die berufsbegleitende Ausbildung nehme ich bewusst in Kauf.',
       'Wenn Sie im kommenden Schuljahr Bedarf haben, stelle ich mich gern vor.'],
      ['Lebenslauf', 'Diplomzeugnis', 'Arbeitszeugnis', 'Hospitationsbestätigung']),
    L('Vertretungsstelle mit Masterabschluss', 'berufseinstieg', 'Vertretungslehrkraft für Englisch und Geschichte (befristet)',
      T('Städtisches Gymnasium Mülheim-Broich', 'Ritterstraße 21', '45479 Mülheim an der Ruhr', 'none'),
      ['für die Elternzeitvertretung im Fach Englisch suchen Sie eine Lehrkraft ab Februar. Ich habe meinen Master in Anglistik und Geschichte im vergangenen Jahr abgeschlossen und arbeite seitdem als Lektorin in einem Schulbuchverlag. Dabei habe ich gemerkt, dass ich lieber vor der Klasse stehe als hinter den Arbeitsblättern.',
       'Während des Studiums habe ich drei Jahre lang Englisch-Nachhilfe gegeben, überwiegend für Oberstufenschülerinnen kurz vor dem Abitur. Im Verlag erstelle ich Übungsmaterial für die Sekundarstufe I und kenne die Kernlehrpläne deshalb gut. Ein Jahr Auslandsstudium in Leeds hat mein Englisch auf C2-Niveau gebracht.',
       'Mir ist bewusst, dass eine Vertretungsstelle befristet ist. Für mich ist sie der Test, ob ich danach den Weg ins Lehramt gehe. Ich kann zum 1. Februar beginnen.'],
      ['Lebenslauf', 'Masterzeugnis', 'Nachweis Auslandsstudium', 'Arbeitszeugnis'], frm=['Clara Neumann', 'Kaiserstraße 8', '45468 Mülheim an der Ruhr']),
  ],
  cv=dict(avatar='a14', design='classic', accent=0, name='Dr.-Ing. Petra Hagedorn', title='Dipl.-Ing. Elektrotechnik', street='Rüttenscheider Straße 95', city='45130 Essen',
    exp=[['04/2015', '', 'Entwicklungsingenieurin Messtechnik', 'Windtec Sensorik GmbH', 'Essen', '- Entwicklung von Sensoren für Rotorblätter\n- Ausbildungsbeauftragte für Elektroniker/innen\n- Betreuung der Schüler-AG „Jugend forscht“ (seit 2021)'],
         ['10/2010', '03/2015', 'Wissenschaftliche Mitarbeiterin', 'Lehrstuhl für Messtechnik, Universität', 'Duisburg', '- Promotion, Betreuung von Übungen und Laborpraktika']],
    edu=[['2004', '2010', 'Diplom Elektrotechnik', 'Technische Universität', 'Dortmund', ''],
         ['', '2015', 'Promotion (Dr.-Ing.)', 'Universität', 'Duisburg', '']],
    courses=[['', '2026', 'Hospitation Klasse 8, Physik (2 Wochen)', 'Gesamtschule Essen-Nord', '', ''], ['', '2024', 'Ausbildereignung (AEVO)', 'IHK Essen', '', '']],
    skills=[['Physik und Mathematik', 5], ['Erklären komplexer Inhalte', 5], ['Projektarbeit mit Jugendlichen', 4], ['Digitale Messwerterfassung', 5], ['Präsentation', 4]],
    langs=[['Deutsch', 'native'], ['Englisch', 'C1']],
    hobbies='Chor, Segeln auf dem Baldeneysee'),
  do=['Informier dich über die Regeln deines Bundeslandes und nenn den passenden Weg.', 'Zeig Erklär-Erfahrung mit konkreten Beispielen.', 'Sag offen, dass du die berufsbegleitende Ausbildung machen willst.'],
  dont=['Das Lehramtsstudium kleinreden.', 'Nur mit dem Fachwissen argumentieren – Pädagogik zählt.', 'Unterrichtsfächer angeben, für die dein Abschluss nicht reicht.'],
  questions=['Warum wollen Sie Lehrerin werden – und warum jetzt?', 'Wie gehen Sie mit einer unruhigen Klasse um?', 'Wie würden Sie den Satz des Pythagoras in einer 8. Klasse einführen?', 'Wie stellen Sie sich die Zusammenarbeit im Kollegium vor?'],
  pay='Die Eingruppierung von Quer- und Seiteneinsteigern ist in jedem Land eigens geregelt und hängt vom Abschluss und vom Qualifizierungsweg ab. Frag bei der Schulbehörde oder im Gespräch genau nach.',
  faq=[F('Kann ich mich direkt bei der Schule bewerben?', 'Das hängt vom Land ab. Teils schreiben Schulen Stellen selbst aus, teils läuft die Bewerbung über ein Landesportal oder die Schulbehörde. Lies die Ausschreibung genau, und richte das Anschreiben an die dort genannte Stelle.'),
       F('Welche Fächer haben gute Chancen?', 'Häufig gesucht werden MINT-Fächer, Informatik, Musik, Kunst, Sport und berufliche Fächer an Berufsschulen. Welche Fächer aktuell im Quereinstieg geöffnet sind, legt jedes Land fest.')],
  related=['nachhilfelehrer', 'erzieherin', 'sozialarbeiter', 'schulbegleiter'])
